package com.carebridge.backend.integration;
import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import com.carebridge.backend.common.config.JpaAuditingConfig;import com.carebridge.backend.config.MockMvcSecurityBuilderConfig;import com.carebridge.backend.partner.controller.PartnerPerformanceController;import com.carebridge.backend.partner.dto.response.PartnerPerformanceResponse;import com.carebridge.backend.partner.service.PartnerPerformanceService;import com.carebridge.backend.security.config.SecurityConfig;import com.carebridge.backend.security.jwt.JwtTokenProvider;import com.carebridge.backend.security.repository.UserRepository;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;import org.springframework.context.annotation.*;import org.springframework.security.test.context.support.WithMockUser;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;
@WebMvcTest(value=PartnerPerformanceController.class,excludeFilters=@ComponentScan.Filter(type=FilterType.ASSIGNABLE_TYPE,classes=JpaAuditingConfig.class))@Import({SecurityConfig.class,MockMvcSecurityBuilderConfig.class})class PartnerPerformanceIntegrationTest{static final UUID OWNER=UUID.fromString("fa000000-0000-0000-0000-000000000001");@Autowired MockMvc mvc;@MockitoBean PartnerPerformanceService service;@MockitoBean JwtTokenProvider jwt;@MockitoBean UserRepository users;PartnerPerformanceResponse response(){return new PartnerPerformanceResponse(Map.of("APPROVED",2L),Map.of("PENDING",1L),3,null,null,Instant.now());}
@Test @WithMockUser(username="fa000000-0000-0000-0000-000000000001",roles="PARTNER")void ppfTc503_usesOnlyCurrentActorOrg()throws Exception{when(service.getPerformance(any(),eq(OWNER))).thenReturn(response());mvc.perform(get("/api/v1/partner/performance")).andExpect(status().isOk()).andExpect(jsonPath("$.data.activeExpertLinks").value(3));verify(service).getPerformance(any(),eq(OWNER));}
@Test @WithMockUser(username="fa000000-0000-0000-0000-000000000001",roles="PARTNER")void ppfTcInt001_returnsCounts()throws Exception{when(service.getPerformance(any(),eq(OWNER))).thenReturn(response());mvc.perform(get("/api/v1/partner/performance")).andExpect(status().isOk()).andExpect(jsonPath("$.data.serviceListingsByStatus.APPROVED").value(2));}
@Test @WithMockUser(username="fa000000-0000-0000-0000-000000000001",roles="PARTNER")void ppfTcInt002_readDoesNotCallMutation()throws Exception{when(service.getPerformance(any(),eq(OWNER))).thenReturn(response());mvc.perform(get("/api/v1/partner/performance")).andExpect(status().isOk());verify(service).getPerformance(any(),eq(OWNER));verifyNoMoreInteractions(service);}}
